bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || { echo VIDEO_REPLACEMENT_POLLER_DOWN; exit 61; }
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,
 database:process.env.VIDEOBOT_DB_NAME,
 password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),
 max:1,connectionTimeoutMillis:4500});
try{
 const schema=await pool.query("SELECT to_regclass('public.videobot_rich_offer_receipts') IS NOT NULL AS available");
 if(schema.rows[0]?.available!==true)process.exit(71);
 const receipt=await pool.query("SELECT status,sale_mode,paid_message_id FROM videobot_post_receipts WHERE delivery_key=$1",['v26nov24invoice:1']);
 if(receipt.rows.length!==1||receipt.rows[0].status!=='sent'||receipt.rows[0].sale_mode!=='invoice'||!Number(receipt.rows[0].paid_message_id))
  process.exit(72);
 const rich=await pool.query("SELECT status,message_id FROM videobot_rich_offer_receipts WHERE delivery_key=$1",['v26nov24invoice:1']);
 if(rich.rows.length!==0)process.exit(73);
 console.log('VIDEO_REPLACEMENT_SCHEMA_AND_ORIGINAL_RECEIPT=READY');
}finally{await pool.end()}
JS
